    {
      "path": "awesomplete.js",
      "sha256": "b60dd8ec51ae96e979d58de3e9681449056b74a3d44031eb1121f325bc2e3af6",
      "before": "_ITEM = function (text, input, item_id) {
    var html = input.trim() === "" ? text : text.replace(RegExp($.regExpEscape(input.trim()), "gi"), "<mark>$&</mark>");
    return $.create("li", {
        innerHTML: html,
        role: "option",
        "aria-selected": "false",
        tabindex: "0", // for the Talkback screen reader
        id: "awesomplete_list_" + this.count + "_item_" + item_id
    });
};",
      "after": "_ITEM = function (text, input, item_id) {
    var html = input.trim() === "" ? text : text.replace(RegExp($.regExpEscape(input.trim()), "gi"), "<mark>$&</mark>");
    return $.create("li", {
        innerHTML: html,
        role: "option",
        "aria-selected": "false",
        id: "awesomplete_list_" + this.count + "_item_" + item_id
    });
};"
    },
    {
      "path": "awesomplete.js",
      "sha256": "b60dd8ec51ae96e979d58de3e9681449056b74a3d44031eb1121f325bc2e3af6",
      "before": ""keydown": function(evt) {
            var c = evt.keyCode;

            // If the dropdown `ul` is in view, then act on keydown for the following keys:
            // Enter / Esc / Up / Down
            if(me.opened) {
                if (c === 13 && me.selected) { // Enter
                    evt.preventDefault();
                    me.select(undefined, undefined, evt);
                }
                else if (c === 9 && me.selected && me.tabSelect) {
                    evt.preventDefault();
                    me.select(undefined, undefined, evt);
                }
                else if (c === 27) { // Esc
                    me.close({ reason: "esc" });
                }
                else if (c === 38 || c === 40) { // Down/Up arrow
                    evt.preventDefault();
                    me[c === 38? "previous" : "next"]();
                }
            }
        }",
      "after": ""keydown": function(evt) {
            var c = evt.keyCode;

            // If the dropdown `ul` is in view, then act on keydown for the following keys:
            // Enter / Esc / Up / Down
            if(me.opened) {
                if (c === 13 && me.selected) { // Enter
                    evt.preventDefault();
                    me.select(undefined, undefined, evt);
                }
                else if (c === 9 && me.selected && me.tabSelect) {
                    evt.preventDefault();
                    me.select(undefined, undefined, evt);
                }
